// Package devboard writes devboard task files — the live-telemetry YAML
// rendered by the devboard dashboard (see devboard/schema.md at the repo
// root). Worklog is the privileged writer of these files, never a required
// one: everything here is a silent no-op when the devboard data dir does
// not exist, and hand-written schema-valid files remain fully supported.
//
// Ownership rule (schema.md): every shared field has exactly one author;
// mirroring flows worklog→devboard only.
package devboard

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"gopkg.in/yaml.v3"

	"github.com/prestontallen/ai-devboard/worklog/internal/lockfile"
)

// Schema mirror of devboard/schema.md v1. Extra preserves unknown
// top-level fields across read-modify-write cycles (comments are not
// preserved — documented limitation).
type Task struct {
	Schema int    `yaml:"schema"`
	Title  string `yaml:"title,omitempty"`
	// "epic" marks an epic container; "spike" marks investigation-first
	// work, which the UI renders on a short phase track.
	Type       string        `yaml:"type,omitempty"`
	Branch     string        `yaml:"branch,omitempty"`
	Session    string        `yaml:"session,omitempty"`
	Worklog    string        `yaml:"worklog,omitempty"`
	Tier       *int          `yaml:"tier,omitempty"`
	Complexity string        `yaml:"complexity,omitempty"` // low|medium|high; throttles fan-out
	Phase      string        `yaml:"phase,omitempty"`
	Plan       []PlanItem    `yaml:"plan,omitempty"`
	Score      []ScoreItem   `yaml:"scorecard,omitempty"`
	Decision   []Decision    `yaml:"decisions,omitempty"`
	Code       []CodeRef     `yaml:"code,omitempty"`
	NeedsYou   []NeedsItem   `yaml:"needs_you,omitempty"`
	WaitingOn  []WaitingItem `yaml:"waiting_on,omitempty"`
	Links      []Link        `yaml:"links,omitempty"`
	// Children carries one entry per child ticket when Type == "epic". An
	// epic file's own Branch/Session/Phase/Plan/Score/Decision/Code/
	// NeedsYou/WaitingOn/Links are unused — that in-flight detail lives
	// per child here instead, since more than one child can be active in
	// ## Now at once and a single shared surface would let them overwrite
	// each other.
	Children []ChildEntry   `yaml:"children,omitempty"`
	Extra    map[string]any `yaml:",inline"`
}

// Child state values for ChildEntry.State.
const (
	ChildPending = "pending"
	ChildActive  = "active"
	ChildDone    = "done"
)

// ChildEntry is one child ticket's roster row plus its own in-flight detail
// — the same shape a standalone ticket file carries, nested instead of
// shared, so concurrently active children never collide.
type ChildEntry struct {
	ID         string        `yaml:"id"`
	Title      string        `yaml:"title,omitempty"`
	State      string        `yaml:"state"` // pending|active|done
	Branch     string        `yaml:"branch,omitempty"`
	Session    string        `yaml:"session,omitempty"`
	Tier       *int          `yaml:"tier,omitempty"`
	Complexity string        `yaml:"complexity,omitempty"`
	Phase      string        `yaml:"phase,omitempty"`
	Plan       []PlanItem    `yaml:"plan,omitempty"`
	Score      []ScoreItem   `yaml:"scorecard,omitempty"`
	Decision   []Decision    `yaml:"decisions,omitempty"`
	Code       []CodeRef     `yaml:"code,omitempty"`
	NeedsYou   []NeedsItem   `yaml:"needs_you,omitempty"`
	WaitingOn  []WaitingItem `yaml:"waiting_on,omitempty"`
	Links      []Link        `yaml:"links,omitempty"`
}

// ChildIdentity is the roster input to SyncEpicRoster: just enough to
// place a child on the epic card, sourced from notes/<epicID>.md and
// WORK.md's Active children — never the child's in-flight detail, which
// SyncEpicRoster must not disturb.
type ChildIdentity struct {
	ID    string
	Title string
	State string // pending|active|done
}

type PlanItem struct {
	Text  string `yaml:"text"`
	State string `yaml:"state"` // pending|in_progress|done|blocked
}

type ScoreItem struct {
	Text   string `yaml:"text"`
	Verify string `yaml:"verify,omitempty"`
	Status string `yaml:"status"` // pending|pass|fail
}

type Decision struct {
	What string `yaml:"what"`
	Why  string `yaml:"why,omitempty"`
	When string `yaml:"when,omitempty"`
}

type CodeRef struct {
	File    string `yaml:"file"`
	Lines   string `yaml:"lines,omitempty"`
	Lang    string `yaml:"lang,omitempty"`
	Note    string `yaml:"note,omitempty"`
	Snippet string `yaml:"snippet,omitempty"`
}

type NeedsItem struct {
	Type   string `yaml:"type,omitempty"` // question|checkpoint
	Text   string `yaml:"text"`
	Detail string `yaml:"detail,omitempty"`
}

type Link struct {
	Label string `yaml:"label,omitempty"`
	URL   string `yaml:"url"`
}

// WaitingItem is a question blocked on an EXTERNAL party — another team or
// person, expected to sit for days. Distinct from NeedsItem (blocked on the
// task's own human, resolvable in minutes).
type WaitingItem struct {
	Text   string `yaml:"text"`
	Who    string `yaml:"who"`             // who owes the answer; required
	Asked  string `yaml:"asked,omitempty"` // YYYY-MM-DD; age renders from this
	Link   string `yaml:"link,omitempty"`  // where it was asked
	Detail string `yaml:"detail,omitempty"`
}

// CloseWaitingOn converts every remaining waiting_on entry into an
// "unanswered at close" decision and clears the list, so closing a task
// never silently drops an outstanding question. Shared by the ticketed
// done path (OnDone) and the ticketless CLI path (waiting-on resolve all).
func CloseWaitingOn(t *Task, when string) {
	for _, w := range t.WaitingOn {
		t.Decision = append(t.Decision, Decision{
			What: "unanswered at close: " + w.Text + " (" + w.Who + ")",
			When: when,
		})
	}
	t.WaitingOn = nil
}

// DataDir returns the devboard data directory: $DEVBOARD_DATA, defaulting
// to ~/.local/share/devboard.
func DataDir() string {
	if d := os.Getenv("DEVBOARD_DATA"); d != "" {
		return d
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return ""
	}
	return filepath.Join(home, ".local", "share", "devboard")
}

// Enabled reports whether the data dir exists. Callers must treat a false
// result as "do nothing, succeed" — devboard is opt-in by dir presence.
func Enabled() bool {
	d := DataDir()
	if d == "" {
		return false
	}
	fi, err := os.Stat(d)
	return err == nil && fi.IsDir()
}

// Find locates an existing task file <data>/<repo>/<slug>.{yaml,yml} across
// all repo groups. Returns "" (no error) when absent.
func Find(slug string) (string, error) {
	root := DataDir()
	entries, err := os.ReadDir(root)
	if err != nil {
		return "", err
	}
	for _, e := range entries {
		if !e.IsDir() || strings.HasPrefix(e.Name(), ".") {
			continue
		}
		for _, ext := range []string{".yaml", ".yml"} {
			p := filepath.Join(root, e.Name(), slug+ext)
			if fi, err := os.Stat(p); err == nil && fi.Mode().IsRegular() {
				return p, nil
			}
		}
	}
	return "", nil
}

// List returns every task file path grouped under the data dir.
func List() ([]string, error) {
	root := DataDir()
	entries, err := os.ReadDir(root)
	if err != nil {
		return nil, err
	}
	var out []string
	for _, e := range entries {
		if !e.IsDir() || strings.HasPrefix(e.Name(), ".") {
			continue
		}
		files, err := os.ReadDir(filepath.Join(root, e.Name()))
		if err != nil {
			continue
		}
		for _, f := range files {
			name := strings.ToLower(f.Name())
			if f.Type().IsRegular() && (strings.HasSuffix(name, ".yaml") || strings.HasSuffix(name, ".yml")) {
				out = append(out, filepath.Join(root, e.Name(), f.Name()))
			}
		}
	}
	return out, nil
}

// RepoName derives the grouping directory for new task files: the basename
// of the repository, falling back to the cwd basename outside a repo.
//
// Resolution goes through the *common* git dir rather than the worktree
// root. `git rev-parse --show-toplevel` answers with the linked worktree's
// own path, so every task file created from a worktree used to be filed
// under a group named after the worktree instead of the repo — silently, in
// a directory that only ever held that one file.
func RepoName() string {
	if name := repoNameFromCommonDir(); name != "" {
		return name
	}
	// Older git has no --path-format (added in 2.31). Fall back to the
	// worktree root, which is correct everywhere except inside a linked
	// worktree — i.e. those users keep the old behavior rather than gaining
	// a new failure.
	if out, err := exec.Command("git", "rev-parse", "--show-toplevel").Output(); err == nil {
		if top := strings.TrimSpace(string(out)); top != "" {
			return filepath.Base(top)
		}
	}
	wd, err := os.Getwd()
	if err != nil {
		return "unknown"
	}
	return filepath.Base(wd)
}

// repoNameFromCommonDir resolves the repository name via the common git dir,
// which points at the main repository from anywhere — main checkout, linked
// worktree, or any subdirectory of either. Returns "" when git can't answer,
// leaving the caller to fall back.
func repoNameFromCommonDir() string {
	out, err := exec.Command("git", "rev-parse", "--path-format=absolute", "--git-common-dir").Output()
	if err != nil {
		return ""
	}
	dir := strings.TrimSpace(string(out))
	if dir == "" || !filepath.IsAbs(dir) {
		return ""
	}
	dir = filepath.Clean(dir)

	// Normal repo: the common dir is <root>/.git, so the repo is its parent.
	if filepath.Base(dir) == ".git" {
		return filepath.Base(filepath.Dir(dir))
	}
	// Bare repo: the common dir *is* the repository (e.g. …/foo.git).
	return strings.TrimSuffix(filepath.Base(dir), ".git")
}

// PendingNewGroup returns the repo group name when devboard is enabled and
// that group has no directory yet — i.e. the next task file written will
// create it. Empty otherwise.
//
// A brand-new group is usually just the first ticket in a new repo, but it is
// also exactly what a misresolved repo name looks like. The two are
// indistinguishable here, so this reports rather than decides: callers surface
// it and let the human notice a name that isn't their repo.
func PendingNewGroup() string {
	if !Enabled() {
		return ""
	}
	repo := RepoName()
	if repo == "" {
		return ""
	}
	if fi, err := os.Stat(filepath.Join(DataDir(), repo)); err == nil && fi.IsDir() {
		return ""
	}
	return repo
}

// gitBranch returns the current branch name, or "" outside a repo.
func gitBranch() string {
	out, err := exec.Command("git", "rev-parse", "--abbrev-ref", "HEAD").Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(out))
}

// Mutate performs a locked, atomic read-modify-write of the task file at
// path. When the file is absent it starts from an empty schema-1 task.
// A file that exists but fails to parse aborts before fn runs, leaving the
// file byte-identical.
func Mutate(path string, fn func(*Task) error) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	unlock, err := lockfile.Acquire(path + ".lock")
	if err != nil {
		return err
	}
	defer unlock()

	t := &Task{Schema: 1}
	raw, err := os.ReadFile(path)
	switch {
	case err == nil:
		if uerr := yaml.Unmarshal(raw, t); uerr != nil {
			return fmt.Errorf("devboard: %s is not valid YAML (file left untouched): %w", path, uerr)
		}
		if t.Schema == 0 {
			t.Schema = 1
		}
	case errors.Is(err, os.ErrNotExist):
		// fresh task
	default:
		return err
	}

	if err := fn(t); err != nil {
		return err
	}

	out, err := yaml.Marshal(t)
	if err != nil {
		return err
	}
	tmp, err := os.CreateTemp(filepath.Dir(path), ".devboard-*")
	if err != nil {
		return err
	}
	tmpName := tmp.Name()
	if _, err := tmp.Write(out); err != nil {
		tmp.Close()
		os.Remove(tmpName)
		return err
	}
	if err := tmp.Close(); err != nil {
		os.Remove(tmpName)
		return err
	}
	if err := os.Rename(tmpName, path); err != nil {
		os.Remove(tmpName)
		return err
	}
	return nil
}

// pathFor returns the existing file for slug, or the creation path in the
// current repo group when none exists.
func pathFor(slug string) (string, error) {
	if p, err := Find(slug); err != nil || p != "" {
		return p, err
	}
	return filepath.Join(DataDir(), RepoName(), slug+".yaml"), nil
}

// today is stubbed in tests.
var today = func() string { return time.Now().Format("2006-01-02") }

// --- worklog lifecycle side effects -----------------------------------
// All three are silent no-ops when devboard is not Enabled. Errors are
// returned for the caller to WARN on — a devboard failure must never fail
// the worklog operation itself.

// OnStart guarantees a task file exists for the started ticket, carrying
// identity fields. It does NOT set phase — phases are agent-driven.
//
// blockType mirrors the ticket's WORK.md Type ("spike", "chore"); empty for
// an ordinary ticket. Like title, it is identity rather than workflow state
// — the board reads it to pick the short research track for a spike.
func OnStart(id, title, blockType string) error {
	if !Enabled() {
		return nil
	}
	path, err := pathFor(id)
	if err != nil {
		return err
	}
	return Mutate(path, func(t *Task) error {
		created := t.Title == "" && t.Worklog == ""
		// "epic" belongs to SyncEpicRoster; a start must never overwrite it.
		if blockType != "" && blockType != "ticket" && t.Type != "epic" {
			t.Type = blockType
		}
		if title != "" {
			t.Title = title
		}
		t.Worklog = id
		if s := os.Getenv("CLAUDE_CODE_SESSION_ID"); s != "" {
			t.Session = s
		}
		if created {
			if b := gitBranch(); b != "" {
				t.Branch = b
			}
		}
		return nil
	})
}

// OnDone marks the task done and clears the attention queue. No-op when no
// task file exists for the ticket.
func OnDone(id string) error {
	if !Enabled() {
		return nil
	}
	path, err := Find(id)
	if err != nil || path == "" {
		return err
	}
	return Mutate(path, func(t *Task) error {
		t.Phase = "done"
		t.NeedsYou = nil
		CloseWaitingOn(t, today())
		return nil
	})
}

// SyncEpicRoster ensures an epic's task file carries Type "epic", its
// title, and an up-to-date roster: every entry in roster is upserted by
// ID, updating only Title/State (identity) — an existing child's
// in-flight detail (Branch/Phase/Plan/Score/... , set separately via
// MutateChild) is never touched. Children not present in roster are left
// as-is rather than pruned, since the notes-file scan this is sourced
// from is expected to be append-only. Silent no-op when devboard is
// disabled, same contract as OnStart/OnDone.
func SyncEpicRoster(epicID, epicTitle string, roster []ChildIdentity) error {
	if !Enabled() {
		return nil
	}
	path, err := pathFor(epicID)
	if err != nil {
		return err
	}
	return Mutate(path, func(t *Task) error {
		t.Type = "epic"
		if epicTitle != "" {
			t.Title = epicTitle
		}
		t.Worklog = epicID
		for _, ci := range roster {
			if idx := indexOfChild(t.Children, ci.ID); idx >= 0 {
				if ci.Title != "" {
					t.Children[idx].Title = ci.Title
				}
				t.Children[idx].State = ci.State
			} else {
				t.Children = append(t.Children, ChildEntry{ID: ci.ID, Title: ci.Title, State: ci.State})
			}
		}
		return nil
	})
}

// MutateChild performs a locked, atomic read-modify-write of one child's
// entry within an epic's task file at path, identified by childID. A
// child not yet on the roster is appended with State ChildPending before
// fn runs — the roster sync from a real ticket start will correct its
// identity later. Callers gate Enabled()/taskDisabled themselves, matching
// Mutate's contract.
func MutateChild(path, childID string, fn func(*ChildEntry) error) error {
	return Mutate(path, func(t *Task) error {
		idx := indexOfChild(t.Children, childID)
		if idx < 0 {
			t.Children = append(t.Children, ChildEntry{ID: childID, State: ChildPending})
			idx = len(t.Children) - 1
		}
		return fn(&t.Children[idx])
	})
}

// indexOfChild returns the index of the child with the given ID
// (case-insensitive, matching worklog's ID normalization elsewhere), or -1.
func indexOfChild(children []ChildEntry, id string) int {
	for i, c := range children {
		if strings.EqualFold(c.ID, id) {
			return i
		}
	}
	return -1
}

// OnPR sets (or clears, url=="") the PR link on the ticket's task file.
// No-op when no task file exists.
func OnPR(id, url string) error {
	if !Enabled() {
		return nil
	}
	path, err := Find(id)
	if err != nil || path == "" {
		return err
	}
	return Mutate(path, func(t *Task) error {
		kept := t.Links[:0]
		for _, l := range t.Links {
			if l.Label != "PR" {
				kept = append(kept, l)
			}
		}
		t.Links = kept
		if url != "" {
			t.Links = append(t.Links, Link{Label: "PR", URL: url})
		}
		return nil
	})
}

#!/usr/bin/env python3
"""Devboard: dashboard over a directory of task files.

Layout: <DEVBOARD_DATA>/<repo>/<task>.{yaml,yml,json}
        <DEVBOARD_DATA>/<repo>/_archive/<task>.yaml   (archived; flagged in API)
Endpoints:
  /               -> static/index.html
  /api/tasks      -> all tasks, parsed, grouped by repo dir, plus the
                     global friction log parsed from the worklog mount
  /events         -> SSE stream; emits a message whenever the data dir changes
  /api/archive    -> POST {repo, id}: move task file into <repo>/_archive/
  /api/unarchive  -> POST {repo, id}: move it back

The two POST endpoints are the server's only writes, and both are a single
validated rename — task content and the worklog dir are never touched.
"""

import json
import os
import re
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

import yaml

DATA_DIR = os.environ.get("DEVBOARD_DATA", "/data")
WORKLOG_DIR = os.environ.get("DEVBOARD_WORKLOG", "/worklog")  # notes/<id>.md + FEEDBACK.md, read-only
PORT = int(os.environ.get("DEVBOARD_PORT", "8484"))
SCAN_INTERVAL = float(os.environ.get("DEVBOARD_SCAN_INTERVAL", "1.0"))
STATIC_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "static")
TASK_EXTS = (".yaml", ".yml", ".json")
ARCHIVE_DIR = "_archive"  # per-repo subdir; the only place the server ever moves files
FEEDBACK_MD = "FEEDBACK.md"  # friction log at the worklog root; written only by the worklog CLI

# Entry heading in FEEDBACK.md: "## <unix-ts> — <signal>" (em dash).
FEEDBACK_HEADING = re.compile(r"^## (\d+) \u2014 (\S+)$")

_version = 0
_changed = threading.Condition()


def _snapshot():
    """Map of watched-file path -> (mtime, size) for change detection.
    Covers task files, worklog notes and FEEDBACK.md, so note edits and
    newly captured (or resolved) friction hot-reload too."""
    snap = {}
    try:
        with os.scandir(DATA_DIR) as repos:
            for repo in repos:
                if not repo.is_dir() or repo.name.startswith("."):
                    continue
                with os.scandir(repo.path) as files:
                    for f in files:
                        if f.is_file() and f.name.lower().endswith(TASK_EXTS):
                            st = f.stat()
                            snap[f.path] = (st.st_mtime_ns, st.st_size)
                try:
                    with os.scandir(os.path.join(repo.path, ARCHIVE_DIR)) as arc:
                        for f in arc:
                            if f.is_file() and f.name.lower().endswith(TASK_EXTS):
                                st = f.stat()
                                snap[f.path] = (st.st_mtime_ns, st.st_size)
                except (FileNotFoundError, NotADirectoryError):
                    pass
    except FileNotFoundError:
        pass
    try:
        fpath = os.path.join(WORKLOG_DIR, FEEDBACK_MD)
        st = os.stat(fpath)
        snap[fpath] = (st.st_mtime_ns, st.st_size)
    except (FileNotFoundError, NotADirectoryError, PermissionError):
        pass
    try:
        with os.scandir(os.path.join(WORKLOG_DIR, "notes")) as notes:
            for f in notes:
                if f.is_file() and f.name.lower().endswith(".md"):
                    st = f.stat()
                    snap[f.path] = (st.st_mtime_ns, st.st_size)
    except (FileNotFoundError, NotADirectoryError, PermissionError):
        pass
    return snap


def _watcher():
    global _version
    prev = _snapshot()
    while True:
        time.sleep(SCAN_INTERVAL)
        cur = _snapshot()
        if cur != prev:
            prev = cur
            with _changed:
                _version += 1
                _changed.notify_all()


def _parse_task(path, archived=False):
    rel = os.path.relpath(path, DATA_DIR)
    entry = {"file": rel, "id": os.path.splitext(os.path.basename(path))[0]}
    if archived:
        entry["archived"] = True
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as fh:
            raw = fh.read()
        data = json.loads(raw) if path.lower().endswith(".json") else yaml.safe_load(raw)
        if not isinstance(data, dict):
            raise ValueError("top level must be a mapping")
        entry["task"] = data
        st = os.stat(path)
        entry["mtime"] = st.st_mtime
        wl = data.get("worklog")
        if isinstance(wl, str) and wl and "/" not in wl and ".." not in wl:
            np = os.path.join(WORKLOG_DIR, "notes", wl + ".md")
            try:
                with open(np, "r", encoding="utf-8", errors="replace") as nf:
                    entry["notes"] = nf.read()
            except OSError:
                pass  # no notes file: section simply absent
    except Exception as exc:  # any bad file becomes an error card, never a 500
        entry["error"] = f"{type(exc).__name__}: {exc}"
    return entry


def _parse_feedback():
    """Parse FEEDBACK.md into a list of entries, oldest first.

    Mirrors the format written by `worklog feedback` (Go:
    internal/feedback/feedback.go). Deliberately permissive — an unknown
    "**Field**:" line is skipped rather than failing, so the Go side can add
    fields without breaking the board. Any read or parse problem yields an
    empty list: friction is a side panel and must never take down the page.
    """
    try:
        with open(os.path.join(WORKLOG_DIR, FEEDBACK_MD), "r",
                  encoding="utf-8", errors="replace") as fh:
            lines = fh.read().split("\n")
    except OSError:
        return []

    entries, cur, in_excerpt = [], None, False
    for line in lines:
        m = FEEDBACK_HEADING.match(line)
        if m:
            if cur:
                entries.append(cur)
            cur = {"timestamp": int(m.group(1)), "signal": m.group(2),
                   "trigger": "", "excerpt": "", "context": "", "resolved": 0}
            in_excerpt = False
            continue
        if cur is None:
            continue
        if line.startswith("**Trigger**: "):
            cur["trigger"] = line[len("**Trigger**: "):]
            in_excerpt = False
        elif line == "**Excerpt**:":
            in_excerpt = True
        elif line.startswith("**Context**: "):
            cur["context"] = line[len("**Context**: "):]
            in_excerpt = False
        elif line.startswith("**Resolved**: "):
            raw = line[len("**Resolved**: "):].strip()
            cur["resolved"] = int(raw) if raw.isdigit() else 0
            in_excerpt = False
        elif line.startswith("**"):
            in_excerpt = False  # unknown field: skip the line, keep the entry
        elif in_excerpt:
            text = line[2:] if line.startswith("> ") else line
            cur["excerpt"] = cur["excerpt"] + "\n" + text if cur["excerpt"] else text
    if cur:
        entries.append(cur)
    for e in entries:
        e["excerpt"] = e["excerpt"].strip()
    return entries


def _all_tasks():
    repos = []
    try:
        names = sorted(
            d for d in os.listdir(DATA_DIR)
            if not d.startswith(".") and os.path.isdir(os.path.join(DATA_DIR, d))
        )
    except FileNotFoundError:
        names = []
    for name in names:
        rdir = os.path.join(DATA_DIR, name)
        tasks = [
            _parse_task(os.path.join(rdir, f))
            for f in sorted(os.listdir(rdir))
            if f.lower().endswith(TASK_EXTS) and os.path.isfile(os.path.join(rdir, f))
        ]
        arcdir = os.path.join(rdir, ARCHIVE_DIR)
        if os.path.isdir(arcdir):
            tasks += [
                _parse_task(os.path.join(arcdir, f), archived=True)
                for f in sorted(os.listdir(arcdir))
                if f.lower().endswith(TASK_EXTS) and os.path.isfile(os.path.join(arcdir, f))
            ]
        if tasks:
            repos.append({"repo": name, "tasks": tasks})
    with _changed:
        v = _version
    return {"version": v, "generated": time.time(), "repos": repos,
            "feedback": _parse_feedback()}


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, fmt, *args):
        pass

    def _send(self, code, body, ctype="application/json"):
        data = body if isinstance(body, bytes) else body.encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        path = self.path.split("?", 1)[0]
        if path in ("/", "/index.html"):
            with open(os.path.join(STATIC_DIR, "index.html"), "rb") as fh:
                self._send(200, fh.read(), "text/html; charset=utf-8")
        elif path == "/api/tasks":
            # default=str: YAML yields dates/times json can't serialize natively
            self._send(200, json.dumps(_all_tasks(), default=str))
        elif path == "/events":
            self._sse()
        elif path in ("/api/archive", "/api/unarchive"):
            self._send(405, '{"error": "POST only"}')
        else:
            self._send(404, '{"error": "not found"}')

    def do_POST(self):
        path = self.path.split("?", 1)[0]
        if path == "/api/archive":
            self._move(to_archive=True)
        elif path == "/api/unarchive":
            self._move(to_archive=False)
        else:
            self._send(404, '{"error": "not found"}')

    def _move(self, to_archive):
        """Rename a task file into or out of <repo>/_archive/ — the server's
        only write. The strict application/json requirement doubles as the
        CSRF guard: cross-origin JSON needs a preflight this server never
        answers, and simple-request content types are rejected here."""
        global _version
        ctype = self.headers.get("Content-Type", "").split(";")[0].strip().lower()
        if ctype != "application/json":
            return self._send(415, '{"error": "Content-Type must be application/json"}')
        try:
            length = int(self.headers.get("Content-Length", "0"))
            body = json.loads(self.rfile.read(length) or b"")
            repo, task_id = body.get("repo"), body.get("id")
        except (ValueError, AttributeError):
            return self._send(400, '{"error": "invalid JSON body"}')
        for part in (repo, task_id):
            if (not isinstance(part, str) or not part or part.startswith(".")
                    or ".." in part or any(c in part for c in "/\\")):
                return self._send(400, '{"error": "invalid repo or id"}')
        repo_dir = os.path.join(DATA_DIR, repo)
        arc_dir = os.path.join(repo_dir, ARCHIVE_DIR)
        src_dir, dst_dir = (repo_dir, arc_dir) if to_archive else (arc_dir, repo_dir)
        fname = None
        if os.path.isdir(src_dir):
            for f in sorted(os.listdir(src_dir)):
                if (f.lower().endswith(TASK_EXTS) and os.path.splitext(f)[0] == task_id
                        and os.path.isfile(os.path.join(src_dir, f))):
                    fname = f
                    break
        if not fname:
            return self._send(404, '{"error": "task not found"}')
        dst = os.path.join(dst_dir, fname)
        if os.path.exists(dst):
            return self._send(409, '{"error": "destination already exists"}')
        try:
            os.makedirs(dst_dir, exist_ok=True)
            os.rename(os.path.join(src_dir, fname), dst)
        except OSError as exc:
            return self._send(500, json.dumps({"error": f"move failed: {exc}"}))
        with _changed:  # wake SSE clients now; don't wait out the scan interval
            _version += 1
            _changed.notify_all()
        self._send(200, json.dumps(
            {"status": "archived" if to_archive else "restored", "repo": repo, "id": task_id}))

    def _sse(self):
        self.send_response(200)
        self.send_header("Content-Type", "text/event-stream")
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        with _changed:
            last = _version
        try:
            self.wfile.write(f"data: {{\"version\": {last}}}\n\n".encode())
            self.wfile.flush()
            while True:
                with _changed:
                    if _version == last:
                        _changed.wait(timeout=15.0)
                    cur = _version
                if cur != last:
                    last = cur
                    self.wfile.write(f"data: {{\"version\": {cur}}}\n\n".encode())
                else:
                    self.wfile.write(b": keepalive\n\n")
                self.wfile.flush()
        except (BrokenPipeError, ConnectionResetError):
            pass


def main():
    threading.Thread(target=_watcher, daemon=True).start()
    server = ThreadingHTTPServer(("0.0.0.0", PORT), Handler)
    print(f"devboard: serving {DATA_DIR} on http://0.0.0.0:{PORT}", flush=True)
    server.serve_forever()


if __name__ == "__main__":
    main()

package model

// State of a top-level worklog item.
type State string

const (
	StatePending State = " "
	StateActive  State = "~"
	StateDone    State = "x"
)

// Label returns the human/JSON-friendly representation of a State:
// "pending" | "active" | "done". Unknown values map to "pending".
func (s State) Label() string {
	switch s {
	case StateActive:
		return "active"
	case StateDone:
		return "done"
	default:
		return "pending"
	}
}

// BlockType distinguishes epic containers from ticket-like blocks.
type BlockType string

const (
	TypeTicket  BlockType = "ticket"
	TypeEpic    BlockType = "epic"
	TypeSpike   BlockType = "spike"
	TypeChore   BlockType = "chore"
	TypeUnknown BlockType = ""
)

// SectionName is one of the canonical WORK.md sections.
type SectionName string

const (
	SectionNow     SectionName = "Now"
	SectionNext    SectionName = "Next"
	SectionSomeday SectionName = "Someday"
	SectionBlocked SectionName = "Blocked"
	SectionWaiting SectionName = "Waiting"
)

// Block is one top-level `- [ ] ...` item plus its indented metadata.
// Line numbers are 1-indexed and inclusive of the block's metadata range.
//
// JSON tags are present on metadata fields; line numbers, section back-
// pointer, and raw state are omitted from JSON because CLI wire types
// translate them into more friendly shapes (e.g. State -> "pending"/"active"/"done").
type Block struct {
	StartLine int `json:"-"`
	EndLine   int `json:"-"`

	Section SectionName `json:"-"`
	State   State       `json:"-"`
	Title   string      `json:"title"`

	ID             string    `json:"id"`
	Type           BlockType `json:"type"`
	Parent         string    `json:"parent"`
	Repo           string    `json:"repo"`
	Tags           []string  `json:"tags"`
	Started        string    `json:"started"`
	PR             string    `json:"pr"`
	Source         string    `json:"source"`
	WaitingSince   string    `json:"waitingSince"`
	Files          []string  `json:"files"`
	Acceptance     string    `json:"acceptance"`
	NotesRef       string    `json:"notesRef"`
	Status         string    `json:"status"`
	Plan           string    `json:"plan"`
	ActiveChildren []string  `json:"activeChildren"`
}

// IsEpic reports whether the block is an epic container.
func (b Block) IsEpic() bool { return b.Type == TypeEpic }

// IsActive reports whether the block is in-progress (`[~]`).
func (b Block) IsActive() bool { return b.State == StateActive }

// IsDone reports whether the block is complete (`[x]`).
func (b Block) IsDone() bool { return b.State == StateDone }

