1	package feedback
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7		"path/filepath"
8		"regexp"
9		"strconv"
10		"strings"
11		"time"
12	
13		"github.com/prestontallen/ai-devboard/worklog/internal/lockfile"
14		"github.com/prestontallen/ai-devboard/worklog/internal/render"
15	)
16	
17	// Signal enumerates the four friction signals the agent watches for.
18	type Signal string
19	
20	const (
21		SignalMissingFeature   Signal = "missing-feature"
22		SignalTUIError         Signal = "tui-error"
23		SignalProfanity        Signal = "profanity"
24		SignalAgentFrustration Signal = "agent-frustration"
25	)
26	
27	// AllSignals returns the valid set, ordered as documented in SKILL.md.
28	func AllSignals() []Signal {
29		return []Signal{SignalMissingFeature, SignalTUIError, SignalProfanity, SignalAgentFrustration}
30	}
31	
32	// IsValidSignal returns true iff s is one of the four enum values.
33	func IsValidSignal(s string) bool {
34		for _, sig := range AllSignals() {
35			if string(sig) == s {
36				return true
37			}
38		}
39		return false
40	}
41	
42	// Entry is one feedback record.
43	//
44	// Timestamp is unix seconds — chosen so headings stay short and the
45	// format is consistent with other shell tooling.
46	type Entry struct {
47		Timestamp int64  `json:"timestamp"`
48		Signal    Signal `json:"signal"`
49		Trigger   string `json:"trigger"` // one-line summary
50		Excerpt   string `json:"excerpt"` // verbatim user/assistant exchange
51		Context   string `json:"context"` // dispatcher's context note
52	
53		// Resolved is the unix time the human marked this entry reviewed, or 0
54		// while it is still outstanding. Written by Resolve, never by Append.
