const fold = (key, label, inner, extra) =>
  `<details class="fold" data-k="${esc(key)}"><summary>${label}</summary>${inner}</details>${extra || ""}`;

/* ---------- friction: the global FEEDBACK.md log ----------
   Global, not per-task: no task-YAML field is involved. The board only ever
   reads it — the worklog mount is read-only, so "resolve" is a copyable CLI
   command, never a button that writes. */
const SIG_ORDER = ["missing-feature", "tui-error", "profanity", "agent-frustration"];
const feedbackAll = () => Array.isArray(DB.feedback) ? DB.feedback : [];
const feedbackOpen = () => feedbackAll().filter(e => !e.resolved);
const stamp = t => t ? new Date(t * 1000).toLocaleString() : "";
const newestFirst = xs => xs.slice().sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));
const resolveBtn = e => e.resolved ? ""
  : `<button class="act" data-c="worklog feedback resolve ${esc(e.timestamp)}" onclick="copyCmd(event, this)" title="copy: worklog feedback resolve ${esc(e.timestamp)}">⧉ resolve cmd</button>`;

function frictionRow(e, i, group) {
  const detail = (e.excerpt ? `<pre>${esc(e.excerpt)}</pre>` : "") +
                 (e.context ? `<div class="fnote">${esc(e.context)}</div>` : "");
  const sub = stamp(e.timestamp) + (e.resolved ? ` · reviewed ${stamp(e.resolved)}` : "");
  return `<div class="need"><span class="kind sig">${esc(e.signal || "?")}</span>` +
    `<div class="what"><b>${esc(e.trigger || "")}</b><small>${esc(sub)}</small></div>` +
    `<span class="go">${resolveBtn(e)}</span></div>` +
    (detail ? fold(`friction|${group}|${i}`, "detail", detail) : "");
}

function frictionHTML() {
  const all = feedbackAll();
  if (!all.length) return "";
  const open = all.filter(e => !e.resolved), done = all.filter(e => e.resolved);
  const signals = [...new Set(open.map(e => e.signal))]
    .sort((a, b) => (SIG_ORDER.indexOf(a) + 1 || 99) - (SIG_ORDER.indexOf(b) + 1 || 99));
  const counts = signals.map(sig =>
    `<span class="chip">${esc(sig)} <b>${open.filter(e => e.signal === sig).length}</b></span>`).join("");
  const body =
    (counts ? `<div class="sigcounts">${counts}</div>` : "") +
    (open.length
      ? newestFirst(open).map((e, i) => frictionRow(e, i, "open")).join("")
      : `<div class="calm">all captured friction reviewed</div>`) +
    (done.length
      ? `<div class="resolvedwrap">` + fold("board|frictiondone", `Resolved · ${done.length}`,
          newestFirst(done).map((e, i) => frictionRow(e, i, "done")).join("")) + `</div>`
      : "");
  return `<section class="bandfold friction">` +
    fold("board|friction", `Friction · ${open.length}`, body) + `</section>`;
}

/* ---------- board ---------- */
function statsHTML() {
  const ts = flat().filter(x => !x.t.error && !isArchived(x.t));
  const inFlight = ts.filter(x => (x.t.task.phase || "") !== "done").length;
  const need = ts.filter(x => (x.t.task.phase || "") !== "done").reduce((a, x) => a + needsCount(x.t), 0);
  const waiting = ts.filter(x => (x.t.task.phase || "") !== "done").reduce((a, x) => a + waitCount(x.t), 0);
  const stale = ts.filter(x => (x.t.task.phase || "") !== "done" && isStale(x.t.mtime)).length;
  const friction = feedbackOpen().length;
  return `<div class="stat"><b>${inFlight}</b><span>in flight</span></div>` +
    (need ? `<div class="stat attn"><b>${need}</b><span>need you</span></div>` : "") +
    (waiting ? `<div class="stat wait"><b>${waiting}</b><span>waiting on</span></div>` : "") +
    (stale ? `<div class="stat"><b>${stale}</b><span>stale</span></div>` : "") +
    (friction ? `<div class="stat"><b>${friction}</b><span>friction</span></div>` : "");
}

const isDone = t => !t.error && (t.task.phase || "") === "done";

/* compact per-card roster: one chip per child, active first, state-colored */
const CHILD_ORDER = { active: 0, pending: 1, done: 2 };
const CHILD_MARK = { active: "▶ ", pending: "○ ", done: "✓ " };
function childrenRosterHTML(children) {
  if (!children.length) return `<div class="calm childrenempty">no children started yet</div>`;
  const sorted = children.slice().sort((a, b) => (CHILD_ORDER[a.state] ?? 1) - (CHILD_ORDER[b.state] ?? 1));
  return `<div class="childroster">` + sorted.map(c => {
    const st = c.state || "pending";
    return `<span class="childchip ${st}" title="${esc(c.title || c.id)} · ${esc(st)}">` +
      (CHILD_MARK[st] || "") + esc(c.title || c.id) + `</span>`;
  }).join("") + `</div>`;
}

function cardHTML({ repo, t }) {
  if (t.error) {
    return `<div class="card errcard"><div class="head"><span class="t">${esc(t.file)}</span></div>` +
           `<span class="badge-err">parse error</span><div class="msg">${esc(t.error)}</div></div>`;
  }
  const k = t.task, n = needsCount(t), wn = waitCount(t);
  const stale = isStale(t.mtime) && !isDone(t);
  if (k.type === "epic") {
    const children = k.children || [];
    const activeN = children.filter(c => c.state === "active").length;
    return `<a class="card${n ? " attn" : ""}" href="#${esc(repo)}/${esc(t.id)}">` +
      `<div class="head"><span class="t">${esc(k.title || t.id)}</span>` +
      (n ? `<span class="flag">needs you · ${n}</span>` : "") +
      (wn ? `<span class="chip waitchip">⧖ ${wn}</span>` : "") +
      `<span class="chip epicbadge">◆ epic</span>` +
      `<span class="chip">${esc(repo)}</span></div>` +
      childrenRosterHTML(children) +
      `<div class="foot">` +
      `<span>${children.length} ${children.length === 1 ? "child" : "children"}` +
      (activeN ? ` · ${activeN} active` : "") + `</span>` +
      `<span class="sp"></span>${k.worklog ? "☰ " + esc(k.worklog) : ""}` +
      ((isDone(t) || isArchived(t)) ? " " + moveBtn(repo, t) : "") + `</div></a>`;
  }
  const meta = [
    k.tier !== undefined ? `tier ${esc(k.tier)}` : "",
    k.complexity ? `cx ${esc(k.complexity)}` : "",
    k.worklog ? `☰ ${esc(k.worklog)}` : "",
  ].filter(Boolean).join(" · ");
  return `<a class="card${n ? " attn" : ""}${stale ? " stale" : ""}" href="#${esc(repo)}/${esc(t.id)}">` +
    `<div class="head"><span class="t">${esc(k.title || t.id)}</span>` +
    (n ? `<span class="flag">needs you · ${n}</span>` : "") +
    (wn ? `<span class="chip waitchip">⧖ ${wn}</span>` : "") +
    (k.type === "spike" ? `<span class="chip spikebadge">◇ spike</span>` : "") +
    `<span class="chip">${esc(repo)}</span></div>` +
    trackHTML(k.phase, k.type) + metersHTML(k) +
    `<div class="foot">` +
    (t.mtime ? `<span class="dot${stale ? " old" : ""}"></span>${ago(t.mtime)}${stale ? " — stale" : ""}` : "") +
    `<span class="sp"></span>${meta} ${resumeBtn(k, "⧉")}` +
    ((isDone(t) || isArchived(t)) ? " " + moveBtn(repo, t) : "") + `</div></a>`;
}

